bist_esp_err_t bist_ext_crystal_fail_test(void)
{
#if SOC_XT_WDT_SUPPORTED
    esp_err_t err;

    esp_xt_wdt_config_t cfg = {
        .timeout = 200,
        .auto_backup_clk_enable = false,
    };

    esp_xt_wdt_register_callback(test_callback, NULL);

    err = esp_xt_wdt_init(&cfg);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "Failed to initialize external watchdog timer");
        return BIST_ESP_CLOCK_TEST_ERR;
    }

    ets_delay_us(2000);

    if (test_failed) {
        test_failed = false;
        return BIST_ESP_CLOCK_TEST_ERR;
    }

#else
    /* SoCs without XT WDT have no hardware to detect 32k crystal
     * failure; skip this test and report OK. */
    ESP_LOGD(TAG, "SoCs without XT WDT have no hardware to detect 32k crystal failure; skipping test.");
#endif

    return BIST_ESP_OK;
}

bist_esp_err_t bist_main_crystal_test(void)
{
    uint32_t xtal_freq_mhz = rtc_clk_xtal_freq_get();
    uint32_t expected_xtal_freq = xtal_freq_mhz * MHZ;

    /*
     * rtc_clk_cal returns the 32K XTAL clock period in fixed-point format (Q13.19).
     * If the main XTAL drifts, the returned value shifts proportionally.
     */
    uint32_t cal_val = rtc_clk_cal(CLK_CAL_32K_XTAL, 500);
    if (cal_val == 0) {
        return BIST_ESP_CLOCK_TEST_ERR;
    }

    /*
     * Derive actual XTAL frequency from the calibration result:
     */
    uint32_t xtal_freq = (uint32_t)(((uint64_t)cal_val * xtal_freq_mhz * 32768) >> RTC_CLK_CAL_FRACT);
    float deviation = fabs((float)(int)(xtal_freq - expected_xtal_freq)) / expected_xtal_freq * 100;

    /*
     * Check if the calculated XTAL frequency is within
     * CONFIG_ESP_BIST_CLOCK_PERCENT_FREQUENCY_DRIFT
     */
    if (deviation > CONFIG_ESP_BIST_CLOCK_PERCENT_FREQUENCY_DRIFT) {
        return BIST_ESP_CLOCK_TEST_ERR;
    }

    return BIST_ESP_OK;
}

bist_esp_err_t bist_wdt_test(void)
{
    volatile uint32_t wdt_timeout_us = 10000;
    soc_reset_reason_t reset = esp_rom_get_reset_reason(0);

    if (reset == RESET_REASON_CORE_MWDT0) {
        return BIST_ESP_OK;
    }

    BIST_ADD_LABEL("bist_test_wdt_timeout");

    wdt_init(wdt_timeout_us);

    /* let watchdog callback happen or timeout */
    ets_delay_us(50000);

    wdt_deinit();

    return BIST_ESP_WDT_TEST_ERR;
}

static bist_esp_err_t bist_gpio_set_and_check_level(gpio_num_t gpio_num, int set_level)
{
    if (gpio_set_level(gpio_num, set_level) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to set GPIO %d to %d", gpio_num, set_level);
        return BIST_ESP_IO_TEST_ERR;
    }

    int level = gpio_get_level(gpio_num);

    if (level != set_level) {
        ESP_LOGE(TAG, "GPIO %d output test failed, expected level: %d, got: %d", gpio_num, set_level, level);
        return BIST_ESP_IO_TEST_ERR;
    }

    return BIST_ESP_OK;
}

bist_esp_err_t bist_gpio_output_test(gpio_num_t gpio_num)
{
    if (!GPIO_IS_VALID_GPIO(gpio_num)) {
        ESP_LOGE(TAG, "GPIO number error: %d", gpio_num);
        return BIST_ESP_IO_TEST_ERR;
    }

    if(gpio_reset_pin(gpio_num) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to reset GPIO %d", gpio_num);
        return BIST_ESP_IO_TEST_ERR;
    }

    if (gpio_set_direction(gpio_num, GPIO_MODE_INPUT_OUTPUT) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to set GPIO %d as output", gpio_num);
        return BIST_ESP_IO_TEST_ERR;
    }

    if (bist_gpio_set_and_check_level(gpio_num, 0) != BIST_ESP_OK) {
        return BIST_ESP_IO_TEST_ERR;
    }

    if (bist_gpio_set_and_check_level(gpio_num, 1) != BIST_ESP_OK) {
        return BIST_ESP_IO_TEST_ERR;
    }

    if(gpio_reset_pin(gpio_num) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to reset GPIO %d", gpio_num);
        return BIST_ESP_IO_TEST_ERR;
    }

    return BIST_ESP_OK;
}

bist_esp_err_t bist_gpio_input_test(gpio_num_t gpio_num, bool expected_level)
{
    if (!GPIO_IS_VALID_GPIO(gpio_num)) {
        ESP_LOGE(TAG, "GPIO number error: %d", gpio_num);
        return BIST_ESP_IO_TEST_ERR;
    }

    if(gpio_reset_pin(gpio_num) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to reset GPIO %d", gpio_num);
        return BIST_ESP_IO_TEST_ERR;
    }

    if (gpio_set_direction(gpio_num, GPIO_MODE_INPUT) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to set GPIO %d as input", gpio_num);
        return BIST_ESP_IO_TEST_ERR;
    }

    if (gpio_get_level(gpio_num) != expected_level) {
        ESP_LOGE(TAG, "GPIO input test failed for GPIO %d, expected level: %d", gpio_num, expected_level);
        return BIST_ESP_IO_TEST_ERR;
    }

    if(gpio_reset_pin(gpio_num) != ESP_OK) {
        ESP_LOGE(TAG, "Failed to reset GPIO %d", gpio_num);
        return BIST_ESP_IO_TEST_ERR;
    }

    return BIST_ESP_OK;
}

esp_err_t esp_timer_create(const esp_timer_create_args_t* args,
                           esp_timer_handle_t* out_handle)
{

    if (args == NULL || args->callback == NULL || out_handle == NULL) {
        return ESP_ERR_INVALID_ARG;
    }

    esp_timer_handle_t result = (esp_timer_handle_t) calloc(1, sizeof(*result));
    if (result == NULL) {
        return ESP_ERR_NO_MEM;
    }

    result->callback = args->callback;
    result->arg = args->arg;
    result->flags = (args->dispatch_method ? FL_ISR_DISPATCH_METHOD : 0) |
                    (args->skip_unhandled_events ? FL_SKIP_UNHANDLED_EVENTS : 0);
    *out_handle = result;
    return ESP_OK;
}

esp_err_t esp_timer_start_periodic(esp_timer_handle_t timer, uint64_t period_us)
{
    if (timer == NULL) {
        return ESP_ERR_INVALID_ARG;
    }

    period_us = MAX(period_us, esp_timer_impl_get_min_period_us());
    int64_t alarm = systimer_hal.ticks_to_us(systimer_hal_get_counter_value(&systimer_hal, SYSTIMER_COUNTER_ESPTIMER)) + period_us;
    esp_err_t err;

    /* Check if the timer is armed once the list is locked to avoid a data race */
    if (timer_armed(timer)) {
        err = ESP_ERR_INVALID_STATE;
    } else {
        timer->alarm = alarm;
        timer->period = period_us;
        err = timer_insert(timer, false);
    }
    return err;
}

esp_err_t esp_timer_delete(esp_timer_handle_t timer)
{
    if (timer == NULL) {
        return ESP_ERR_INVALID_ARG;
    }

    int64_t alarm = systimer_hal.ticks_to_us(systimer_hal_get_counter_value(&systimer_hal, SYSTIMER_COUNTER_ESPTIMER));
    esp_err_t err;

    /* Check if the timer is armed once the list is locked to avoid a data race */
    if (timer_armed(timer)) {
        err = ESP_ERR_INVALID_STATE;
    } else {
        // A case for the timer with ESP_TIMER_ISR:
        // This ISR timer was removed from the ISR list in esp_timer_stop() or in timer_process_alarm() -> LIST_REMOVE(it, list_entry)
        // and here this timer will be added to another the TASK list, see below.
        // We do this because we want to free memory of the timer in a task context instead of an isr context.
        timer->flags &= ~FL_ISR_DISPATCH_METHOD;
        timer->event_id = EVENT_ID_DELETE_TIMER;
        timer->alarm = alarm;
        timer->period = 0;
        err = timer_insert(timer, false);
    }
    return err;
}

esp_err_t esp_timer_init(void)
{
    /* Guard avoids -Wdeprecated-declarations on SoCs where IDF retired
     * the legacy API (C5/C61/...); SYSTIMER is on by reset default there. */
#ifdef __PERIPH_CTRL_ALLOW_LEGACY_API
    periph_module_enable(PERIPH_SYSTIMER_MODULE);
#endif
    systimer_hal_tick_rate_ops_t ops = {
        .ticks_to_us = systimer_ticks_to_us,
        .us_to_ticks = systimer_us_to_ticks,
    };
    systimer_hal_init(&systimer_hal);
    systimer_hal_set_tick_rate_ops(&systimer_hal, &ops);

    systimer_hal_enable_counter(&systimer_hal, SYSTIMER_COUNTER_ESPTIMER);
    systimer_hal_select_alarm_mode(&systimer_hal, SYSTIMER_ALARM_ESPTIMER, SYSTIMER_ALARM_MODE_ONESHOT);
    systimer_hal_connect_alarm_counter(&systimer_hal, SYSTIMER_ALARM_ESPTIMER, SYSTIMER_COUNTER_ESPTIMER);

    esp_cpu_intr_disable(1 << ETS_INTERNAL_TIMER0_INTR_NO);
    esp_rom_route_intr_matrix(esp_cpu_get_core_id(), ETS_SYSTIMER_TARGET2_INTR_SOURCE, ETS_INTERNAL_TIMER0_INTR_NO);

    esp_cpu_intr_set_type(ETS_INTERNAL_TIMER0_INTR_NO, 0);
    esp_cpu_intr_set_priority(ETS_INTERNAL_TIMER0_INTR_NO, 2);
    esp_cpu_intr_set_handler(ETS_INTERNAL_TIMER0_INTR_NO, timer_alarm_isr, NULL);

    systimer_hal_enable_alarm_int(&systimer_hal, SYSTIMER_ALARM_ESPTIMER);


    esp_cpu_intr_enable(1 << ETS_INTERNAL_TIMER0_INTR_NO);

    return ESP_OK;

}

esp_err_t esp_timer_deinit(void)
{
    /* Check if there are any active timers */
    for (esp_timer_dispatch_t dispatch_method = ESP_TIMER_TASK; dispatch_method < ESP_TIMER_MAX; ++dispatch_method) {
        if (!LIST_EMPTY(&s_timers[dispatch_method])) {
            return ESP_ERR_INVALID_STATE;
        }
    }

    systimer_ll_enable_alarm(systimer_hal.dev, SYSTIMER_ALARM_ESPTIMER, false);
    systimer_ll_enable_alarm_int(systimer_hal.dev, SYSTIMER_ALARM_ESPTIMER, false);
    esp_cpu_intr_disable(1 << ETS_INTERNAL_TIMER0_INTR_NO);

    return ESP_OK;
}

int64_t esp_timer_get_time(void)
{
    // we hope the execution time of this function won't > 1us
    // thus, to save one function call, we didn't use the existing `systimer_hal_get_time`
    return systimer_hal.ticks_to_us(systimer_hal_get_counter_value(&systimer_hal, SYSTIMER_COUNTER_ESPTIMER));
}

